<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { Plus, Award, Camera, Star, Medal, Shield, UserRound, RefreshCw } from '@lucide/vue'
import { api } from '../../services/api'
import { authStore } from '../../stores/auth'
import { uiStore } from '../../stores/ui'
import { number, positionName } from '../../utils'
import PageHeader from '../../components/PageHeader.vue'
import LoadingBlock from '../../components/LoadingBlock.vue'
import EntityAvatar from '../../components/EntityAvatar.vue'
import RankMovement from '../../components/RankMovement.vue'
import HonourMedals from '../../components/HonourMedals.vue'
import EmptyState from '../../components/EmptyState.vue'
import BaseModal from '../../components/BaseModal.vue'
import SmartAwardsPanel from '../../components/SmartAwardsPanel.vue'
import PerformanceRatingPanel from '../../components/PerformanceRatingPanel.vue'

const isAdmin=computed(()=>authStore.isAdmin.value)
const loading=ref(true),category=ref('OVERALL'),rankings=ref([]),awardTypes=ref([]),seasons=ref([]),players=ref([]),competitions=ref([])
const eligibleRoster=ref([]),competitionClubs=ref([]),modal=ref(''),busy=ref(false),form=ref({})
const viewMode=ref('honours'),honourScope=ref('players'),honourSeason=ref(''),playerHonours=ref([]),clubHonours=ref([])
const eligiblePlayers=computed(()=>{if(!eligibleRoster.value.length)return players.value;const ids=new Set(eligibleRoster.value.filter(r=>r.status==='ACTIVE').map(r=>Number(r.player_id)));return players.value.filter(p=>ids.has(Number(p.id)))})
async function loadRank(){rankings.value=(await api.get('/rankings/players',{category:category.value,limit:100})).data}
async function loadHonours(){const q={limit:200,season_id:honourSeason.value||undefined};const [p,c]=await Promise.all([api.get('/honours/players',q),api.get('/honours/clubs',q)]);playerHonours.value=p.data;clubHonours.value=c.data}
async function load(){loading.value=true;try{const [a,s,p,c]=await Promise.all([api.get('/award-types'),api.get('/seasons'),api.get('/players',{limit:100}),api.get('/competitions',{limit:100})]);awardTypes.value=a.data;seasons.value=s.data;players.value=p.data;competitions.value=c.data;await Promise.all([loadRank(),loadHonours()])}catch(e){uiStore.notify(e.message,'error')}finally{loading.value=false}}
onMounted(load)
watch(()=>form.value.competition_id,async competitionId=>{if(modal.value!=='award'||!competitionId){eligibleRoster.value=[];competitionClubs.value=[];return}try{const [participants,roster]=await Promise.all([api.get(`/competitions/${competitionId}/participants`),api.get(`/competitions/${competitionId}/rosters`)]);competitionClubs.value=participants.data.filter(p=>p.registration_status==='APPROVED');eligibleRoster.value=roster.data.filter(r=>isAdmin.value||Number(r.club_id)===Number(authStore.user.value.clubId))}catch(e){uiStore.notify(e.message,'error')}})
watch(()=>form.value.player_id,playerId=>{if(modal.value!=='award')return;const rosterEntry=eligibleRoster.value.find(item=>Number(item.player_id)===Number(playerId)&&item.status==='ACTIVE');const player=players.value.find(item=>Number(item.id)===Number(playerId));form.value.club_id_at_award=isAdmin.value?(rosterEntry?.club_id||player?.club_id||''):authStore.user.value.clubId})
function openAward(){eligibleRoster.value=[];competitionClubs.value=[];form.value={player_id:'',club_id_at_award:isAdmin.value?'':authStore.user.value.clubId,competition_id:'',award_type_id:''};modal.value='award'}
function openType(){form.value={code:'',name:'',category:'BEST_PLAYER',required_medal_type:'NONE',base_ranking_points:'0'};modal.value='type'}
async function createType(){busy.value=true;try{const r=await api.post('/award-types',form.value);awardTypes.value.push(r.data);uiStore.notify('Đã tạo loại danh hiệu.');modal.value=''}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function assign(){busy.value=true;try{await api.post('/player-awards',form.value);uiStore.notify('Đã ghi danh hiệu vào lịch sử cầu thủ.');modal.value='';await Promise.all([loadRank(),loadHonours()])}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
function openSnapshot(){form.value={season_id:'',entity:'ALL',club_id:'',category:''};modal.value='snapshot'}
async function snapshot(){busy.value=true;try{await api.post('/rankings/snapshot',form.value);uiStore.notify('Đã chụp BXH để tính mũi tên tăng/giảm.');modal.value='';loadRank()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function backfillFinishedMedals(){
  if(!window.confirm('Hệ thống sẽ rà soát toàn bộ giải đã kết thúc, khôi phục đội hình theo lịch sử CLB và bổ sung HCV/HCB/HCĐ còn thiếu cho cầu thủ. Tiếp tục?'))return
  busy.value=true
  try{
    const result=await api.post('/competitions/backfill-finished-team-medals',{})
    uiStore.notify(result.data?.message||'Đã bổ sung huy chương các giải cũ.')
    await Promise.all([loadRank(),loadHonours()])
  }catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}
}
</script>
<template><div><PageHeader eyebrow="Honours & Ranking" title="Danh hiệu và xếp hạng" description="Xếp hạng huy chương của cầu thủ, thành tích CLB và các chỉ số chuyên môn theo mùa giải."><button v-if="isAdmin" class="btn" @click="openType"><Award :size="17"/>Tạo loại danh hiệu</button><button v-if="isAdmin" class="btn" @click="openAward"><Plus :size="17"/>Trao thủ công ngoại lệ</button><button v-if="isAdmin" class="btn" :disabled="busy" @click="backfillFinishedMedals"><RefreshCw :size="17"/>Bổ sung huy chương giải cũ</button><button v-if="isAdmin" class="btn btn-primary" @click="openSnapshot"><Camera :size="17"/>Chụp BXH</button></PageHeader><PerformanceRatingPanel :competitions="competitions" :is-admin="isAdmin" @updated="loadRank();loadHonours()"/><SmartAwardsPanel v-if="isAdmin" @updated="loadRank();loadHonours()"/><LoadingBlock v-if="loading"/><template v-else><div class="main-tabs glass"><button :class="{active:viewMode==='honours'}" @click="viewMode='honours'"><Medal :size="17"/>BXH danh hiệu</button><button :class="{active:viewMode==='performance'}" @click="viewMode='performance'"><Star :size="17"/>BXH chuyên môn</button></div><template v-if="viewMode==='honours'"><section class="honour-toolbar"><div class="scope-tabs"><button class="btn" :class="{active:honourScope==='players'}" @click="honourScope='players'"><UserRound :size="16"/>Cầu thủ</button><button class="btn" :class="{active:honourScope==='clubs'}" @click="honourScope='clubs'"><Shield :size="16"/>Câu lạc bộ</button></div><select v-model="honourSeason" class="select" @change="loadHonours"><option value="">Toàn bộ lịch sử</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select><button class="btn btn-icon" @click="loadHonours"><RefreshCw :size="17"/></button></section><section class="glass card honours-card"><div class="section-title"><div><span class="eyebrow"><Medal :size="14"/> Hall of Fame</span><h2>{{ honourScope==='players'?'Huy chương cầu thủ':'Thành tích câu lạc bộ' }}</h2><p>{{ honourScope==='players'?'Ví dụ: 1 HCV tại CLB A, 2 HCB tại CLB B vẫn được lưu vĩnh viễn khi chuyển CLB.':'Xếp theo HCV, HCB, HCĐ, số lần vào tứ kết và điểm thành tích.' }}</p></div></div><template v-if="honourScope==='players'"><EmptyState v-if="!playerHonours.length"/><div v-else class="table-wrap"><table><thead><tr><th>Hạng</th><th>Cầu thủ</th><th>CLB hiện tại</th><th>Huy chương</th><th>Giải cá nhân</th><th>Lịch sử</th></tr></thead><tbody><tr v-for="r in playerHonours" :key="r.player_id"><td><b class="rank">#{{ r.rank_position }}</b></td><td><RouterLink :to="`/players/${r.player_id}`" class="entity"><EntityAvatar :src="r.photo_url" :name="r.full_name" :size="38" round/><span><b class="entity-name">{{ r.full_name }}</b><small>{{ positionName(r.position) }} · #{{ r.shirt_number||'—' }}</small></span></RouterLink></td><td>{{ r.current_club_name||'Tự do' }}</td><td><HonourMedals compact :gold="r.gold_count" :silver="r.silver_count" :bronze="r.bronze_count"/></td><td><b>{{ r.individual_award_count }}</b><small class="muted-block">{{ number(r.honour_points) }} điểm</small></td><td class="history-cell">{{ r.medal_history||'Chưa có huy chương' }}</td></tr></tbody></table></div></template><template v-else><EmptyState v-if="!clubHonours.length"/><div v-else class="table-wrap"><table><thead><tr><th>Hạng</th><th>CLB</th><th>Huy chương & cột mốc</th><th>Điểm</th><th>Lịch sử</th></tr></thead><tbody><tr v-for="r in clubHonours" :key="r.club_id"><td><b class="rank">#{{ r.rank_position }}</b></td><td><RouterLink :to="`/clubs/${r.club_id}`" class="entity"><EntityAvatar :src="r.logo_url" :name="r.club_name" :size="40"/><span><b class="entity-name">{{ r.club_name }}</b><small>{{ r.code }}</small></span></RouterLink></td><td><HonourMedals compact :gold="r.gold_count" :silver="r.silver_count" :bronze="r.bronze_count" :quarterfinal="r.quarterfinal_count"/></td><td><b>{{ number(r.honour_points) }}</b><small class="muted-block">{{ r.total_achievements }} thành tích</small></td><td class="history-cell">{{ r.achievement_history||'Chưa có thành tích' }}</td></tr></tbody></table></div></template></section></template><template v-else><div class="category-tabs"><button v-for="c in ['OVERALL','GOALS','GOALKEEPER','WEALTH','MARKET_VALUE']" :key="c" class="btn" :class="{active:category===c}" @click="category=c;loadRank()">{{ c }}</button></div><section class="glass card"><div class="section-title"><div><span class="eyebrow"><Star :size="14"/> Player Ranking</span><h2>BXH cầu thủ</h2></div></div><div class="table-wrap"><table><thead><tr><th>Hạng</th><th>Cầu thủ</th><th>CLB</th><th>Điểm/Chỉ số</th><th>Biến động</th></tr></thead><tbody><tr v-for="r in rankings" :key="r.player_id"><td><b class="rank">#{{ r.rank_position }}</b></td><td><div class="entity"><EntityAvatar :src="r.photo_url" :name="r.full_name" :size="38" round/><span class="entity-name">{{ r.full_name }}</span></div></td><td>{{ r.club_name||'Tự do' }}</td><td><b>{{ number(r.score) }}</b></td><td><RankMovement :change="r.rank_change" :previous="r.previous_rank"/></td></tr></tbody></table></div></section></template></template><BaseModal :open="modal==='type'" title="Tạo loại danh hiệu" @close="modal=''" width="660px"><form class="form-grid" @submit.prevent="createType"><label><span class="label">Mã danh hiệu</span><input v-model="form.code" class="input" required placeholder="BEST_PLAYER"/></label><label><span class="label">Tên danh hiệu</span><input v-model="form.name" class="input" required placeholder="Cầu thủ xuất sắc"/></label><label><span class="label">Phân loại</span><select v-model="form.category" class="select"><option value="TEAM_MEDAL">Huy chương tập thể</option><option value="BEST_PLAYER">Cầu thủ xuất sắc</option><option value="TOP_SCORER">Vua phá lưới</option><option value="BEST_GOALKEEPER">Thủ môn xuất sắc</option><option value="BEST_YOUNG_PLAYER">Cầu thủ trẻ xuất sắc</option><option value="BEST_ASSIST">Kiến tạo xuất sắc</option><option value="OTHER">Khác</option></select></label><label><span class="label">Yêu cầu huy chương</span><select v-model="form.required_medal_type" class="select"><option value="NONE">Không</option><option value="GOLD">Vàng</option><option value="SILVER">Bạc</option><option value="BRONZE">Đồng</option></select></label><label class="form-group full"><span class="label">Điểm xếp hạng cơ bản</span><input v-model="form.base_ranking_points" type="number" min="0" step="0.01" class="input"/></label><div class="form-group full actions"><button type="button" class="btn" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">Tạo danh hiệu</button></div></form></BaseModal><BaseModal :open="modal==='award'" title="Trao danh hiệu cầu thủ" @close="modal=''" width="650px"><form class="form-grid" @submit.prevent="assign"><label class="form-group full"><span class="label">Cầu thủ</span><select v-model="form.player_id" class="select" required><option value="">Chọn cầu thủ</option><option v-for="p in eligiblePlayers" :key="p.id" :value="p.id">{{ p.full_name }} · {{ p.club_name||'Tự do' }}</option></select></label><label class="form-group full"><span class="label">Giải đấu</span><select v-model="form.competition_id" class="select" required><option value="">Chọn giải</option><option v-for="c in competitions" :key="c.id" :value="c.id">{{ c.name }} · {{ c.season_name }}</option></select></label><label class="form-group full"><span class="label">Loại danh hiệu</span><select v-model="form.award_type_id" class="select" required><option value="">Chọn danh hiệu</option><option v-for="a in awardTypes" :key="a.id" :value="a.id">{{ a.name }} · {{ a.category }}</option></select></label><label v-if="isAdmin" class="form-group full"><span class="label">CLB tại thời điểm nhận giải</span><select v-model="form.club_id_at_award" class="select" required><option value="">Chọn CLB</option><option v-for="c in competitionClubs" :key="c.club_id" :value="c.club_id">{{ c.club_name }}</option></select></label><div class="form-group full actions"><button type="button" class="btn" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">Trao danh hiệu</button></div></form></BaseModal><BaseModal :open="modal==='snapshot'" title="Chụp bảng xếp hạng" @close="modal=''" width="580px"><form class="form-grid" @submit.prevent="snapshot"><label class="form-group full"><span class="label">Mùa giải</span><select v-model="form.season_id" class="select" required><option value="">Chọn mùa</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label><span class="label">Đối tượng</span><select v-model="form.entity" class="select"><option value="ALL">Tất cả</option><option value="CLUB">CLB</option><option value="PLAYER">Cầu thủ</option></select></label><label><span class="label">Hạng mục cầu thủ</span><select v-model="form.category" class="select"><option value="">Tất cả</option><option v-for="c in ['OVERALL','GOALS','GOALKEEPER','WEALTH','MARKET_VALUE']" :key="c" :value="c">{{ c }}</option></select></label><div class="form-group full actions"><button type="button" class="btn" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">Chụp BXH</button></div></form></BaseModal></div></template>
<style scoped>.main-tabs{padding:6px;display:inline-flex;gap:5px;margin-bottom:17px}.main-tabs button{border:0;background:transparent;color:var(--muted);padding:11px 16px;border-radius:10px;display:flex;align-items:center;gap:7px;font-weight:800}.main-tabs button.active{background:linear-gradient(135deg,var(--primary),var(--primary-2));color:#fff}.honour-toolbar{display:flex;gap:9px;align-items:center;margin-bottom:13px}.scope-tabs{display:flex;gap:7px;flex:1}.scope-tabs .active,.category-tabs .active{background:linear-gradient(135deg,var(--primary),var(--primary-2));border-color:transparent}.honour-toolbar .select{width:220px}.honours-card{position:relative;overflow:hidden}.honours-card:before{content:'';position:absolute;right:-80px;top:-100px;width:310px;height:310px;background:radial-gradient(circle,rgba(255,195,49,.1),transparent 68%);pointer-events:none}.category-tabs{display:flex;gap:7px;overflow:auto;margin-bottom:18px}.rank{color:var(--yellow)}.actions{display:flex;justify-content:flex-end;gap:9px}.entity span{display:grid}.entity small,.muted-block{display:block;color:var(--muted);font-size:9px;margin-top:3px}.history-cell{max-width:380px;color:var(--muted);font-size:10px;line-height:1.5}.section-title p{margin-top:5px}@media(max-width:760px){.honour-toolbar{align-items:stretch;flex-wrap:wrap}.scope-tabs{width:100%}.honour-toolbar .select{width:auto;flex:1}.main-tabs{display:flex}.main-tabs button{flex:1;justify-content:center}}</style>
